def exam(main,choices=None):
 s='\n'.join(f'{i+1}. {v} — {scores[v]}' for i,v in enumerate(main))
 if choices:s+='\n3. На выбор: '+', '.join(f'{v} — {scores[v]}' for v in choices)
 return s
